'use strict';

// MODULES //

var tape = require( 'tape' );
var sqrt = require( '@stdlib/math/base/special/sqrt' );
var incrnanstdev = require( './../lib' );

// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof incrnanstdev, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns an accumulator function', function test( t ) {
	t.equal( typeof incrnanstdev(), 'function', 'returns a function' );
	t.end();
});

tape( 'the function returns an accumulator function (known mean)', function test( t ) {
	t.equal( typeof incrnanstdev( 3.0 ), 'function', 'returns a function' );
	t.end();
});

tape( 'the function throws an error if provided a non-numeric value', function test( t ) {
	var values;
	var i;
	values = [
		'5',
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided ' + values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			incrnanstdev( value );
		};
	}
});

tape( 'the accumulator function incrementally computes a corrected sample standard deviation while ignoring NaNs', function test( t ) {
	var expected;
	var actual;
	var data;
	var acc;
	var i;

	data = [ 2.0, NaN, 3.0, 2.0, 4.0, NaN, 3.0, 4.0 ];

	expected = [
		0.0,
		0.0,
		sqrt( 0.5 ),
		sqrt( 0.33333333333333337 ),
		sqrt( 0.9166666666666666 ),
		sqrt( 0.9166666666666666 ),
		sqrt( 0.7 ),
		sqrt( 0.8 )
	];

	acc = incrnanstdev();
	actual = new Array( data.length );
	for ( i = 0; i < data.length; i++ ) {
		actual[i] = acc( data[i] );
	}
	t.deepEqual( actual, expected, 'returns expected incremental results' );
	t.end();
});

tape( 'if not provided an input value, the accumulator function returns the current corrected sample standard deviation', function test( t ) {
	var data = [ NaN, 2.0, 3.0, NaN, 1.0 ];
	var acc = incrnanstdev();
	for ( var i = 0; i < data.length; i++ ) {
		acc( data[i] );
	}
	t.equal( acc(), 1.0, 'returns the current accumulated corrected sample standard deviation' );
	t.end();
});

tape( 'if not provided an input value, the accumulator function returns the current corrected sample sample deviation (known mean)', function test( t ) {
	var data;
	var acc;
	var i;

	data = [ 2.0, 3.0, NaN, 1.0 ];
	acc = incrnanstdev( 2.0 );
	for ( i = 0; i < data.length; i++ ) {
		acc( data[ i ] );
	}
	t.equal( acc(), sqrt( 0.6666666666666666 ), 'returns the current accumulated corrected sample standard deviation' );
	t.end();
});

tape( 'the corrected sample standard deviation is `null` until at least 1 datum has been provided (unknown mean)', function test( t ) {
	var acc;
	var s;

	acc = incrnanstdev();

	s = acc();
	t.equal( s, null, 'returns null' );

	s = acc( 3.0 );
	t.notEqual( s, null, 'does not return null' );

	s = acc();
	t.notEqual( s, null, 'does not return null' );

	t.end();
});

tape( 'the corrected sample standard deviation is `null` until at least 1 datum has been provided (known mean)', function test( t ) {
	var acc;
	var s;

	acc = incrnanstdev( 3.0 );

	s = acc();
	t.equal( s, null, 'returns null' );

	s = acc( 3.0 );
	t.notEqual( s, null, 'does not return null' );

	s = acc();
	t.notEqual( s, null, 'does not return null' );

	t.end();
});

tape( 'the corrected sample standard deviation is `0` until at least 2 datums have been provided (unknown mean)', function test( t ) {
	var acc;
	var s;

	acc = incrnanstdev();

	s = acc( 2.0 );
	t.equal( s, 0.0, 'returns 0' );

	s = acc();
	t.equal( s, 0.0, 'returns 0' );

	s = acc( 3.0 );
	t.notEqual( s, 0.0, 'does not return 0' );

	s = acc();
	t.notEqual( s, 0.0, 'does not return 0' );

	t.end();
});

tape( 'if provided only NaNs, the accumulator function returns `null`', function test( t ) {
	var acc = incrnanstdev();
	acc( NaN );
	acc( NaN );
	acc( NaN );
	t.equal( acc(), null, 'returns null' );
	t.end();
});
